Q4. Find the output with suitable explanation for the below given snippets:

Snippet 1 (Left):
```cpp
#include<iosstream>
using namespace std;
class Number{
public:
int x;
Number(){
x=10;
}
Number(int y = 5){
x=y;
}
void display(){
cout<<x;
}
};
int main(){
Number obj1;
obj1.display();
return 0;
}
```

Snippet 2 (Middle):
```cpp
#include<iosstream>
void modifyArray(int *arr, int size){
for(int i=0;i<size;++i){
*arr = (*arr++ * 2) + 5;
arr++;
}
}
int main(){
int arr[]={10,20,30,40,50};
int len=sizeof(arr)/sizeof(arr[0]);
modifyArray(arr,len);
std::cout<<"Modified Array:";
for(int i=0;i<len;i++)
std::cout<<arr[i]<<"\t";
return 0;
}
```

Snippet 3 (Right):
```cpp
#include<iosstream>
void processArray(int* arr, int size){
for(int i=0;i<size;++i){
arr[i] = 2*arr[i] * 2;
}
}
int main(){
int * originalArray=new int[5];
for(int i=0;i<5;++i){
originalArray[i] = i*i + 1;
}
processArray(originalArray,5);
for(int i=0;i<5;++i){
std::cout<<originalArray[i]<<"\t";
}
delete[] originalArray;
return 0;
}
